CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','manager','staff')),password_hash TEXT,active INTEGER NOT NULL DEFAULT 1,verified INTEGER NOT NULL DEFAULT 0,totp_secret TEXT,totp_last_step INTEGER NOT NULL DEFAULT -1,created INTEGER NOT NULL);
CREATE UNIQUE INDEX single_owner ON users(role) WHERE role='owner';
CREATE TABLE stores(id TEXT PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'Australia/Sydney',archived INTEGER NOT NULL DEFAULT 0,tag_hash TEXT NOT NULL UNIQUE,tag_cipher TEXT NOT NULL,latitude REAL,longitude REAL,radius REAL NOT NULL DEFAULT 150,max_accuracy REAL NOT NULL DEFAULT 100,location_required INTEGER NOT NULL DEFAULT 0);
CREATE TABLE memberships(user_id TEXT NOT NULL REFERENCES users(id),store_id TEXT NOT NULL REFERENCES stores(id),PRIMARY KEY(user_id,store_id));
CREATE TABLE shifts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),store_id TEXT NOT NULL REFERENCES stores(id),started INTEGER NOT NULL,ended INTEGER,approval TEXT NOT NULL DEFAULT 'pending' CHECK(approval IN ('pending','approved')),source TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,CHECK(ended IS NULL OR ended>=started));
CREATE UNIQUE INDEX one_open_shift ON shifts(user_id) WHERE ended IS NULL;
CREATE INDEX shift_dates ON shifts(started,ended);
CREATE TABLE breaks(id TEXT PRIMARY KEY,shift_id TEXT NOT NULL REFERENCES shifts(id) ON DELETE CASCADE,started INTEGER NOT NULL,ended INTEGER,paid INTEGER NOT NULL CHECK(paid IN (0,1)),CHECK(ended IS NULL OR ended>=started));
CREATE UNIQUE INDEX one_open_break ON breaks(shift_id) WHERE ended IS NULL;
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL,kind TEXT NOT NULL,entity_id TEXT NOT NULL,before_json TEXT,after_json TEXT,reason TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'Audit records are immutable'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'Audit records are immutable'); END;
CREATE TABLE corrections(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),shift_id TEXT NOT NULL REFERENCES shifts(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',resolution TEXT,created INTEGER NOT NULL,resolved INTEGER);
CREATE TABLE exceptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),store_id TEXT NOT NULL REFERENCES stores(id),action TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',resolution TEXT,created INTEGER NOT NULL,resolved INTEGER);
CREATE TABLE location_events(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,store_id TEXT NOT NULL,action TEXT NOT NULL,latitude REAL,longitude REAL,accuracy REAL,distance REAL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE idempotency(user_id TEXT NOT NULL,key TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(user_id,key));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf TEXT NOT NULL,pending_user TEXT,expires INTEGER NOT NULL,last_seen INTEGER NOT NULL,mfa INTEGER NOT NULL DEFAULT 0,pending_totp TEXT);
CREATE TABLE tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE recovery_codes(user_id TEXT NOT NULL REFERENCES users(id),code_hash TEXT NOT NULL UNIQUE);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE outbox(id TEXT PRIMARY KEY,to_email TEXT NOT NULL,subject TEXT NOT NULL,body_cipher TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,available INTEGER NOT NULL,sent INTEGER,last_error TEXT);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),long_shift_hours INTEGER NOT NULL DEFAULT 16,retention_days INTEGER NOT NULL DEFAULT 0,location_retention_days INTEGER NOT NULL DEFAULT 90,backup_retention_days INTEGER NOT NULL DEFAULT 30);
INSERT INTO settings(id) VALUES(1);
CREATE TRIGGER shifts_no_overlap_insert BEFORE INSERT ON shifts WHEN EXISTS(SELECT 1 FROM shifts WHERE user_id=NEW.user_id AND started<COALESCE(NEW.ended,9223372036854775807) AND COALESCE(ended,9223372036854775807)>NEW.started) BEGIN SELECT RAISE(ABORT,'Overlapping shifts'); END;
CREATE TRIGGER shifts_no_overlap_update BEFORE UPDATE OF started,ended,user_id ON shifts WHEN EXISTS(SELECT 1 FROM shifts WHERE id<>NEW.id AND user_id=NEW.user_id AND started<COALESCE(NEW.ended,9223372036854775807) AND COALESCE(ended,9223372036854775807)>NEW.started) BEGIN SELECT RAISE(ABORT,'Overlapping shifts'); END;
CREATE TRIGGER breaks_valid_insert BEFORE INSERT ON breaks WHEN NOT EXISTS(SELECT 1 FROM shifts WHERE id=NEW.shift_id AND NEW.started>=started AND (ended IS NULL OR NEW.ended IS NOT NULL AND NEW.ended<=ended)) OR EXISTS(SELECT 1 FROM breaks WHERE shift_id=NEW.shift_id AND started<COALESCE(NEW.ended,9223372036854775807) AND COALESCE(ended,9223372036854775807)>NEW.started) BEGIN SELECT RAISE(ABORT,'Invalid or overlapping break'); END;
CREATE TRIGGER breaks_valid_update BEFORE UPDATE ON breaks WHEN NOT EXISTS(SELECT 1 FROM shifts WHERE id=NEW.shift_id AND NEW.started>=started AND (ended IS NULL OR NEW.ended IS NOT NULL AND NEW.ended<=ended)) OR EXISTS(SELECT 1 FROM breaks WHERE id<>NEW.id AND shift_id=NEW.shift_id AND started<COALESCE(NEW.ended,9223372036854775807) AND COALESCE(ended,9223372036854775807)>NEW.started) BEGIN SELECT RAISE(ABORT,'Invalid or overlapping break'); END;
